import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse(`{"title":"What's New — v2.0 to v2.17.0","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/features/whats-new.md","filePath":"openshield-xdp/features/whats-new.md","lastUpdated":1786512085000}`),r={name:"openshield-xdp/features/whats-new.md"};function n(i,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-s-new-—-v2-0-to-v2-17-0" tabindex="-1">What&#39;s New — v2.0 to v2.17.0 <a class="header-anchor" href="#what-s-new-—-v2-0-to-v2-17-0" aria-label="Permalink to &quot;What&#39;s New — v2.0 to v2.17.0&quot;">​</a></h1><p>The feature changelog for the 2.x line. For the complete feature map see <a href="/pingless-studios-docs/openshield-xdp/features/">Everything OpenShield-XDP Does</a>.</p><h2 id="v2-17-0-—-attached-ip-registry-per-tenant-blackhole" tabindex="-1">v2.17.0 — attached-IP registry &amp; per-tenant blackhole <a class="header-anchor" href="#v2-17-0-—-attached-ip-registry-per-tenant-blackhole" aria-label="Permalink to &quot;v2.17.0 — attached-IP registry &amp; per-tenant blackhole&quot;">​</a></h2><p>Built for dedicated hosts carrying many tenant VPSes.</p><ul><li><strong>Attached IPs</strong> — the firewall now learns which destination IPs are yours: wire-observed destinations auto-attach (with noise filtered out), local interface addresses are swept in, and you can add single IPs or whole subnet pools by hand. Every entry carries a last-seen timestamp; auto-detected entries idle for <code>registry.inactive_days</code> (default 14) clean themselves out. Browse and manage from <code>openshield ips</code> or the TUI&#39;s new IPs tab. Attaching never changes how traffic is handled — it&#39;s knowledge, not policy. See <a href="./../guide/attached-ips">Attached IPs</a>.</li><li><strong>Blackhole</strong> — drop <em>everything</em> destined to one tenant IP at the earliest point in the pipeline, until you say otherwise or a timer runs out. Established players (real TCP handshakes) keep playing; they get a 10-minute grace window when they disconnect, and they still face every other check — exemption is from the blackhole only. Your whitelist is evaluated first, so you never lock yourself out. <code>openshield blackhole add/remove/list</code>, or toggle per IP in the TUI. See <a href="./../guide/blackhole">Blackhole</a>.</li><li><strong>Auto-blackhole (opt-in)</strong> — set a per-IP pps/bps magnitude and the firewall blackholes an attached IP that crosses it, extends while the attack persists, and lifts when it&#39;s over. Registry-gated so it can never touch an address you don&#39;t manage; every engage/lift posts an alert with the numbers.</li><li>New metrics for all of it: attached counts by origin, reaped total, active blackholes with remaining time, blackhole-dropped packets, live exemption count, auto-blackhole events.</li><li>Under the hood: config fields can no longer drift between the YAML writer, the TUI metadata and the docs (CI-enforced), a C↔Go struct-layout gate guards the kernel/userspace ABI, and the updater understands same-version hotfix builds.</li></ul><h2 id="v2-16-3-—-carpet-bomb-floods-answered-protection-that-holds-under-churn" tabindex="-1">v2.16.3 — carpet-bomb floods answered, protection that holds under churn <a class="header-anchor" href="#v2-16-3-—-carpet-bomb-floods-answered-protection-that-holds-under-churn" aria-label="Permalink to &quot;v2.16.3 — carpet-bomb floods answered, protection that holds under churn&quot;">​</a></h2><p>Found by our 23-class automated flood matrix (every flood class run against live simulated players); every fix verified on the rig before shipping.</p><ul><li><strong>Carpet-bomb floods can no longer rotate past the caps</strong> — a flood that spreads across thousands of destination ports defeated every <em>per-port</em> defense. New aggregate per-protocol caps close it: <code>dynamic.attack_udp_pps</code> (default 100k/s) watches UDP as a whole, and both it and <code>dynamic.attack_icmp_pps</code> now engage on attack state <strong>or</strong> on an early spike over 8× the learned normal rate for that protocol — inside the first window of the burst. Protected (known-good) sources are exempt, as always.</li><li><strong>Short ICMP bursts no longer outrun mitigation</strong> — the aggregate ICMP cap previously waited for the userspace attack declaration; it now has the same kernel-side early trigger, so seconds-long rotating ICMP floods are capped immediately.</li><li><strong>Legit clients stay protected for the whole fight</strong> — the known-good source set now freezes during any engagement: existing members keep their proof fresh, new admits need an established TCP connection, and nothing expires until 90 seconds of sustained peace. Mid-flood map churn can no longer evict your real players, and flood sources can&#39;t mint themselves &quot;protected&quot; status mid-attack.</li><li>Testing infrastructure: the flood matrix (23 attack classes including every common amplification shape and game-shaped floods) now asserts that Minecraft Java/Bedrock, CS2 and SFTP traffic profiles survive every single class.</li><li><strong>Auto-update fixed for single-activation licenses</strong> — the update download gate re-validated your key under a synthetic identity, which needed a spare activation seat; keys with exactly one seat were refused with <code>invalid license</code>. The updater now presents the machine identity it already owns.</li></ul><h2 id="v2-16-1-—-blacklist-action-un-gated-from-forensics" tabindex="-1">v2.16.1 — blacklist action un-gated from forensics <a class="header-anchor" href="#v2-16-1-—-blacklist-action-un-gated-from-forensics" aria-label="Permalink to &quot;v2.16.1 — blacklist action un-gated from forensics&quot;">​</a></h2><ul><li>Fixed: on a server with forensics collection off (or halted by the disk guard), the attacks-tab <strong>blacklist</strong> action had no <code>ips_involved.txt</code> to read and failed with a bare stat error — zero IPs banned. The involved-IP list is now written at every attack end regardless of the forensics gate, and the block-pattern action tells you plainly when an attack has no fingerprint (payload patterns need pcap data).</li></ul><h2 id="v2-16-0-—-auto-updates-burst-proofing-disk-guardrails" tabindex="-1">v2.16.0 — auto-updates, burst-proofing, disk guardrails <a class="header-anchor" href="#v2-16-0-—-auto-updates-burst-proofing-disk-guardrails" aria-label="Permalink to &quot;v2.16.0 — auto-updates, burst-proofing, disk guardrails&quot;">​</a></h2><ul><li><strong>Signed auto-update channel</strong> — <code>openshield update</code> downloads and installs the latest release for you; licensed installs can also update unattended (<code>updates.auto</code>, default on). The release metadata is Ed25519-signed by the license server, the download is license-gated and short-lived, the zip is hash-verified before anything is touched, and the previous version is restored automatically if the new one fails to start. An update badge in the TUI top bar tells you when a newer release exists.</li><li><strong>Jumbo-packet floods can no longer sneak under the pps cap</strong> — the per-port cap and its early spike trigger now watch bytes too (<code>dynamic.attack_port_bps</code>), so a slow-pps flood of 1400-byte packets is throttled just the same.</li><li><strong>Rotating ICMP floods answered</strong> — new attack-mode aggregate ICMP cap (<code>dynamic.attack_icmp_pps</code>, default 1000/s) while an attack is declared. Normal ping/PMTUD traffic is tens per second and unaffected.</li><li><strong>Your SSH session survives the flood</strong> — <code>dynamic.port_cap_exempt_ports</code> (default <code>[22]</code>) keeps management ports out of the per-port cap forever, even when the flood aims at them.</li><li><strong>Players are protected from the first packet of a burst</strong> — the firewall now maintains its known-good source set continuously instead of snapshotting at attack start (the snapshot provably arrived after flood churn had erased the evidence). Real clients on capped ports no longer share the throttled pool at all.</li><li><strong>It learns from its false alarms</strong> — an &quot;attack&quot; that ends with zero bans and zero dropped packets was a legitimate surge; the baseline now gets a bounded credit to learn that rate instead of re-alerting the same busy hour every day.</li><li><strong>The firewall can never fill your disk again</strong> — forensics are capped at 15% of the hosting filesystem regardless of the configured limit, and collection halts outright under 512MB free (resumes when space returns).</li><li><strong>4GB-tuned defaults</strong> — minimum recommended RAM moves from 2GB to 4GB; default ban map 4M entries, per-IP stats 262k, whitelist 50k. The installer warns on smaller hosts and tells you what to trim.</li><li>CI now runs a live flood regression on every push: the firewall is loaded on a virtual link and must stop real floods while simulated players survive.</li></ul><h2 id="v2-15-2-—-learned-detection-can-be-switched-off" tabindex="-1">v2.15.2 — learned detection can be switched off <a class="header-anchor" href="#v2-15-2-—-learned-detection-can-be-switched-off" aria-label="Permalink to &quot;v2.15.2 — learned detection can be switched off&quot;">​</a></h2><ul><li><strong>New <code>dynamic.baseline_enabled</code> master switch</strong> (default on, applies live — no reload). Turn it off and every <em>learned</em> detection layer goes quiet: baseline learning, seasonal thresholds, the changepoint onset detector and behavior clustering. Attacks then declare purely on your static numbers — <code>attack_min_pps</code>/<code>attack_min_bps</code>, or the explicit <code>attack_pps_threshold</code>/<code>attack_bps_threshold</code> overrides when set. Per-IP rate limiting, suspicion scoring, bans and the attack-mode caps are static mechanisms and keep working unchanged. For servers with spiky-but-legitimate traffic that prefer fixed thresholds.</li></ul><h2 id="v2-15-1-—-burst-flood-bypass-fix" tabindex="-1">v2.15.1 — burst-flood bypass fix <a class="header-anchor" href="#v2-15-1-—-burst-flood-bypass-fix" aria-label="Permalink to &quot;v2.15.1 — burst-flood bypass fix&quot;">​</a></h2><ul><li><strong>Short distributed floods can no longer outrun mitigation.</strong> Every aggregate defense (the per-port cap, per-IP attack cap) used to wait for the userspace attack declaration — a burst of a few seconds could end before it arrived. The per-port cap now also engages on a <strong>kernel-side early spike trigger</strong>: a destination port running over your <code>attack_port_pps</code> cap <em>and</em> over 8× its own learned normal rate is throttled immediately — inside the first window of the burst — while players with established connections stay exempt as before. The learned baseline only updates from calm windows, so the flood itself can&#39;t train it upward mid-attack.</li><li><strong>Attack-type labels are re-verified at attack end</strong> against the aggregate protocol mix — a fast first-second guess can no longer leave an <code>ACK_FLOOD</code> label on what became a UDP flood (or <code>MIXED</code> on a single-protocol flood).</li><li>Fixed <code>Family: &lt;nil&gt;</code> appearing in alert embeds when no fingerprint family was identified.</li></ul><h2 id="v2-15-0-—-self-managing-syn-cookies-richer-attack-reports" tabindex="-1">v2.15.0 — self-managing SYN cookies, richer attack reports <a class="header-anchor" href="#v2-15-0-—-self-managing-syn-cookies-richer-attack-reports" aria-label="Permalink to &quot;v2.15.0 — self-managing SYN cookies, richer attack reports&quot;">​</a></h2><ul><li><strong>SYNPROXY companion rules, managed for you (opt-in)</strong> — the installer now offers to auto-manage the 3 netfilter rules the SYN-cookie mode needs: it verifies iptables is present (offers to install it), then <strong>live-probes the rules on your interface before you commit</strong> — if your server can&#39;t do it, you see the exact reason and choose to skip or stop. At runtime the rules appear when an attack engages the cookie path and are removed when it clears; only OpenShield&#39;s own tagged rules are ever touched. Enable via installer or <code>dynamic.synproxy_companion_auto</code>.</li><li><strong>Attack-end alerts, now in two focused messages</strong> — message 1 stays the operational summary (timeline, mitigation, traffic table, graph, forensics bundle). The new message 2, &quot;Sources &amp; Targets&quot;, shows which of your IPs were attacked (broadcast-looking .255/.0 entries filtered out), the targeted ports (<code>mix</code> when many), top attacking countries, and the <strong>offender list as a .txt grouped by ban reason</strong>.</li><li><strong>Honest attachments</strong> — an embed only ever says &quot;attached as .txt&quot; when the file really is attached; if it can&#39;t be, the top rows are inlined instead. Applies to both attack-end and ban-batch alerts. Also fixed: attack-end alerts could silently omit the country breakdown — they now say when GeoIP is off.</li><li><strong>Ban reasons with teeth</strong> — banned-source events now carry the actual kernel ban reason (<code>pps_exceeded</code>, <code>syn_pps_exceeded</code>, …), which is what powers the reason-grouped offender list above.</li><li><strong>Daily/weekly/monthly reports redesigned</strong> — a headline summary up top, the period&#39;s <strong>top 5 attacks</strong> (peak rate × type × duration), a <strong>mitigation breakdown</strong> showing which protection paths dropped what, SYN-cookie challenge/validation stats, a <strong>period-over-period attack delta</strong>, and attacker/user country lists that never overflow Discord&#39;s limits.</li><li><strong>Optional anonymized attack fingerprints</strong> (default OFF; the installer asks once) — after an attack you can share its shape (type, rates, duration, port classes, source count — never a single IP) to help improve the detection patterns everyone auto-fetches. <code>telemetry.attack_share</code>.</li><li><strong><code>xdp_mode: offload</code> now fails with a clear explanation</strong> instead of an obscure driver error (no NIC can offload this program — use <code>native</code> or <code>auto</code>).</li><li>Hot-patchable stage modules (freplace) are correctly wired to the split pipeline stages.</li><li>Full CI gating on every push: build, format/vet, the entire test suite, both kernel-verifier gates, and release-package smoke tests.</li></ul><h2 id="v2-14-0-—-syn-cookies-ipv6-parity-pinned-bans" tabindex="-1">v2.14.0 — SYN cookies, IPv6 parity, pinned bans <a class="header-anchor" href="#v2-14-0-—-syn-cookies-ipv6-parity-pinned-bans" aria-label="Permalink to &quot;v2.14.0 — SYN cookies, IPv6 parity, pinned bans&quot;">​</a></h2><ul><li><strong>XDP SYN cookies</strong> (<code>dynamic.synproxy_mode</code>: off / adaptive / always) — during SYN floods the firewall answers SYNs itself with cookie challenges; spoofed floods never reach your services while real clients connect normally. <code>adaptive</code> engages only above <code>synproxy_threshold</code> or during an active attack, so peacetime handshakes are never touched. One-time setup note: the loader prints the two sysctl/iptables companion lines if your kernel needs them.</li><li><strong>Faster, future-proof engine layout</strong> — the packet pipeline now runs as chained stages, which removes the &quot;program too large&quot; class of load failures on stricter kernels for good and leaves headroom for more detections.</li><li><strong>IPv6 parity</strong> — connection tracking, per-target traffic stats, and the API-endpoint guard now work on IPv6 the same as IPv4. Also fixes a bug where manually added IPv6 whitelist/ban entries could silently not match.</li><li><strong>Pinned bans</strong> — manual blacklist entries and heavy repeat-offender bans now live in a dedicated tier that flood churn can never evict; the TUI bans tab marks them with a PIN tag.</li><li><strong>UDP response-window watch</strong> (on by default) — sustained spoofed-looking &quot;responses&quot; from service ports (DNS/NTP-style amplification) lose their fast-pass exemption and get scored like any other attacker. Verified zero false positives on real DNS/NTP traffic.</li><li>Per-port rate caps no longer undercount under multi-core floods.</li><li><strong>Five new auto-fetch L7 signatures</strong> (WS-Discovery, STUN, CoAP, mDNS, NTP mode-6) — 10 curated reflection-flood patterns total.</li><li>Attack forensics: SYN fingerprint lines now include the sender&#39;s stack class (Linux-like / Windows-like / network-device), and suppressed junk attacks can no longer reappear in history (&quot;duplicate attacks&quot; fix).</li><li>Edge mitigation: new <code>edge:</code> config section (your existing <code>ovh:</code> config keeps working unchanged); every selected IP now gets its edge firewall enabled, not just the first.</li><li>Reliability: <code>openshield reload</code> no longer overwrites hand-edited config or times out on unchanged map sizes; Ctrl+C during the load prompts no longer leaves the firewall half-attached; <code>openshield unload</code> fails loudly instead of orphaning a running loader; license re-checks can no longer leave the interface unprotected after a transient failure.</li><li>Optional per-customer watermarking on release packages, and <code>scripts/bench.sh</code> for one-command performance runs.</li></ul><h2 id="v2-13-1-—-license-enforcement-hardening" tabindex="-1">v2.13.1 — license enforcement hardening <a class="header-anchor" href="#v2-13-1-—-license-enforcement-hardening" aria-label="Permalink to &quot;v2.13.1 — license enforcement hardening&quot;">​</a></h2><ul><li>The license check&#39;s feature switch now lives inside the loaded firewall program itself (frozen at load) instead of a settings area that admin-level tools could edit — tampering with it no longer has any effect.</li><li>Shipped program package no longer carries source-level debug info.</li><li>License tier changes apply live with zero protection gap and no loss of learned state.</li></ul><h2 id="v2-13-6-—-live-visibility-l7-pattern-feeds" tabindex="-1">v2.13.6 — live visibility + L7 pattern feeds <a class="header-anchor" href="#v2-13-6-—-live-visibility-l7-pattern-feeds" aria-label="Permalink to &quot;v2.13.6 — live visibility + L7 pattern feeds&quot;">​</a></h2><ul><li>Top bar shows the version; Packets panel adds the <em>current interval&#39;s</em> pass/drop %; Mitigation panel adds &quot;IPs live: X pass / Y blocked&quot;. New <code>/metrics</code> fields: <code>live_pass_rate</code>, <code>live_drop_rate</code>, <code>live_ips_passed</code>, <code>live_ips_blocked</code>.</li><li><strong>Auto-fetch L7 attack patterns</strong> (opt-in: <code>auto_fetch.patterns_enabled</code> + <code>pattern_urls</code>) — curated reflection-flood signatures (DNS amp, NTP monlist, SSDP, CLDAP, memcached-UDP) load into free L7 slots and update on the fetch interval. Chosen to never fire on game/enterprise/CDN/bulk traffic.</li></ul><h2 id="v2-13-5-—-live-map-sizing" tabindex="-1">v2.13.5 — live map sizing <a class="header-anchor" href="#v2-13-5-—-live-map-sizing" aria-label="Permalink to &quot;v2.13.5 — live map sizing&quot;">​</a></h2><ul><li><code>maps.ban_max</code>, <code>maps.ip_stats_max</code>, <code>maps.whitelist_max</code> are now real, live settings (TUI config tab / control API). Changes apply immediately with a state-preserving reload — active bans survive the resize.</li></ul><h2 id="v2-13-4-—-self-healing-config-values" tabindex="-1">v2.13.4 — self-healing config values <a class="header-anchor" href="#v2-13-4-—-self-healing-config-values" aria-label="Permalink to &quot;v2.13.4 — self-healing config values&quot;">​</a></h2><ul><li>A config value written by an older version could fail validation and block every <code>openshield reload</code> permanently. Config load now repairs out-of-range values automatically and persists the fix on the next save.</li></ul><h2 id="v2-13-3-—-bans-tab-upgrade" tabindex="-1">v2.13.3 — bans tab upgrade <a class="header-anchor" href="#v2-13-3-—-bans-tab-upgrade" aria-label="Permalink to &quot;v2.13.3 — bans tab upgrade&quot;">​</a></h2><ul><li>Search (<code>/</code>) by IP or ban reason, row scrolling (j/k/arrows, g/G), and <strong>instant unban</strong> — select a row, press <code>u</code>, confirm.</li></ul><h2 id="v2-13-2-—-older-kernel-compatibility-fix" tabindex="-1">v2.13.2 — older-kernel compatibility fix <a class="header-anchor" href="#v2-13-2-—-older-kernel-compatibility-fix" aria-label="Permalink to &quot;v2.13.2 — older-kernel compatibility fix&quot;">​</a></h2><ul><li>Fixes an install failure on kernels before 6.9 (&quot;BPF program is too large&quot;): the newest analysis features are intensive for older kernel verifiers, so the release now ships two program builds — full on 6.9+, a lighter (fully protection-equivalent) build on 5.15–6.8 — and picks automatically at load.</li></ul><h2 id="v2-13-1-—-license-enforcement-hardening-1" tabindex="-1">v2.13.1 — license enforcement hardening <a class="header-anchor" href="#v2-13-1-—-license-enforcement-hardening-1" aria-label="Permalink to &quot;v2.13.1 — license enforcement hardening&quot;">​</a></h2><ul><li><strong>One-click network optimization in the installer, detection-first</strong> — it probes your NIC and only applies what&#39;s missing: queue count matched to your vCPUs, larger RX/TX ring buffers for flood bursts, IRQ spread (skipped when irqbalance manages it), txqueuelen, fq_codel queueing, LRO off. You see the exact change list before saying yes.</li><li><strong>Safe on every host type</strong> — unsupported items are skipped per-item, so VPSes (virtio), dedicated boxes, and multi-tenant hosts all get exactly what their hardware supports and nothing breaks.</li><li>New <code>doctor</code> check reports pending optimizations; the TUI <code>nic_tuning</code> toggle applies the same smart set.</li></ul><h2 id="v2-12-1-—-false-attack-flapping-fix" tabindex="-1">v2.12.1 — false-attack flapping fix <a class="header-anchor" href="#v2-12-1-—-false-attack-flapping-fix" aria-label="Permalink to &quot;v2.12.1 — false-attack flapping fix&quot;">​</a></h2><ul><li><strong>Quiet servers no longer flap</strong> — the new changepoint detector could declare attacks below your configured <code>attack_min_pps</code>/<code>attack_min_bps</code> floors, producing hundreds of 1-2s phantom attacks a day on low-traffic boxes. It now respects the floors.</li><li><strong>Junk-record guard</strong> — an &quot;attack&quot; whose traffic never crossed your own floors is suppressed entirely (no history entry, no webhook, no forensics) and counted in the log. Detector noise can never spam your attack history again.</li></ul><h2 id="v2-12-0-—-connection-state-tracking-season-aware-detection-per-tenant-visibility-🆕" tabindex="-1">v2.12.0 — connection-state tracking, season-aware detection, per-tenant visibility 🆕 <a class="header-anchor" href="#v2-12-0-—-connection-state-tracking-season-aware-detection-per-tenant-visibility-🆕" aria-label="Permalink to &quot;v2.12.0 — connection-state tracking, season-aware detection, per-tenant visibility 🆕&quot;">​</a></h2><p>Kernel &amp; protection:</p><ul><li><strong>Connection-state tracking</strong> — the firewall now follows every connection individually: replies to your own outbound connections (apt, curl, updates) are recognized precisely instead of heuristically, and blind ACK/RST floods are judged against the actual state of each connection. No configuration needed.</li><li><strong>Flood-proof offender records</strong> — repeat offenders can no longer wash out their history during a flood; ban history lives in flood-proof storage, so the escalating 1-day / 7-day tiers engage reliably even against million-source rotating floods.</li><li><strong>Small-packet floods now escalate to long bans</strong> — the heavy-evidence bar was unreachable for 64-byte-packet floods; extreme packet rate alone now qualifies for the escalating ban tiers.</li><li><strong>Established connections during attacks</strong> — peacetime behavior is unchanged (proven connections are never banned); while an attack is actively declared, a once-connected source pushing flood-grade rates now accrues suspicion gradually instead of being fully exempt.</li><li><strong>Rotating-source floods without slowdown</strong> — per-source counting is now lock-free, so million-source rotating floods are handled with no core slowdown.</li></ul><p>Detection intelligence:</p><ul><li><strong>Poison-resistant baselines</strong> — the 30-day baseline history is now merged with robust statistics (median + deviation), so a slow multi-day traffic ramp can&#39;t train the baseline upward. Tunable via <code>dynamic.baseline_mad_k</code> (default 3.5). <a href="/pingless-studios-docs/openshield-xdp/user-guide/baseline-ml">Baseline guide</a></li><li><strong>Season-aware thresholds</strong> — the firewall learns your hour-of-day pattern and automatically relaxes the trigger band during predictably busy hours. Needs ~7 days to warm up per hour, and only ever relaxes — never tightens.</li><li><strong>Faster attack onset</strong> — a changepoint detector declares sharp onsets 1–2 seconds earlier than the spike trigger alone.</li><li><strong>Smarter attack classification</strong> — spoof-distribution, FIN-heavy, payload-shape (randomized vs structured) and port-share hints now refine the attack subtype in reports and forensics; forensics bundles show per-source TCP stack consistency.</li><li><strong>Per-tenant visibility on dedicated hosts</strong> — every hosted IP gets a <code>normal</code> / <code>elevated</code> / <code>under_attack</code> state in the TUI targets panel, attack reports, and <code>GET /metrics/targets</code>. Auto-detected: activates only on multi-IP dedicated hosts — single-IP VPS installs are never treated as dedicated. New knob <code>tenant.mode</code> (<code>auto</code> / <code>on</code> / <code>off</code>). <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">Metrics API</a></li></ul><p>Ops:</p><ul><li><strong>Ban-storage pressure protection</strong> — if ban storage approaches full, OpenShield warns you (dashboard + webhook), reaps expired entries immediately, and as a last resort reclaims blocklist-feed entries (they re-fetch automatically). Attack-driven bans are never pressure-deleted.</li><li><strong><code>openshield doctor</code></strong> — one-command environment health check: kernel, BTF, XDP attach, NIC driver, config, forensics disk, and license. <code>--json</code> output for support tickets. <a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI reference</a></li><li><strong>Generic JSON webhook</strong> — set <code>alerter.generic_webhook_url</code> and every event also posts a JSON envelope (<code>{product, version, event, host, timestamp, data}</code>) to your endpoint — same pacing and rate-limit handling as Discord; embeds and attachments stay Discord-only. <a href="/pingless-studios-docs/openshield-xdp/configuration/alerter">Alerter docs</a></li></ul><h2 id="v2-11-0-—-ovh-edge-mitigation-module" tabindex="-1">v2.11.0 — OVH edge-mitigation module <a class="header-anchor" href="#v2-11-0-—-ovh-edge-mitigation-module" aria-label="Permalink to &quot;v2.11.0 — OVH edge-mitigation module&quot;">​</a></h2><ul><li><strong>Drop attacks at OVH&#39;s edge</strong> — optional module (installer opt-in, marked NEW): banned attacker IPs are pushed to OVH&#39;s network firewall (VAC) so flood traffic never reaches your NIC.</li><li><strong>Guided setup</strong> — API region → app credentials → one browser authorization → service auto-detection (the service routing this machine&#39;s main IPv4 is pre-marked) → pick the service&#39;s IPs to protect. Back navigation on every step.</li><li><strong>Two push modes</strong> — <code>confirmed</code> (verified-heavy / repeat offenders only, near-zero false positives) or <code>all</code> (every detected attacker). Blocklist-feed bans are never pushed.</li><li><strong>OVH limits respected</strong> — 20 rule slots per IP (worst offenders first), token-bucket API pacing with 429 backoff, all configurable. Runtime toggle in live settings; status on <code>GET /metrics/ovh</code>.</li></ul><h2 id="v2-10-0-—-forensics-disk-guard" tabindex="-1">v2.10.0 — forensics disk guard <a class="header-anchor" href="#v2-10-0-—-forensics-disk-guard" aria-label="Permalink to &quot;v2.10.0 — forensics disk guard&quot;">​</a></h2><ul><li><strong>Custom forensics directory</strong> (<code>forensics.dir</code>) and a <strong>disk cap</strong> (<code>forensics.max_size_mb</code>, default 30 GB) with automatic oldest-first cleanup of completed attack bundles (<code>cleanup_percent</code>, default 50) — whole bundles only, never half a forensics dir.</li><li><strong>Disk-pressure halt/resume</strong> — if a live capture alone exceeds the cap, collection pauses (pcap stops, future attacks skip forensics) and auto-resumes when space recovers. A manual <code>forensics.collect: false</code> is never overridden; the toggle is in live settings (TUI config tab / control API) and persisted.</li><li><strong><code>GET /metrics/forensics</code></strong> — dir, size vs cap, collecting/halted state, cleanup counters.</li></ul><h2 id="v2-9-1-—-target-list-hygiene" tabindex="-1">v2.9.1 — target-list hygiene <a class="header-anchor" href="#v2-9-1-—-target-list-hygiene" aria-label="Permalink to &quot;v2.9.1 — target-list hygiene&quot;">​</a></h2><ul><li>Multicast/broadcast destinations no longer appear in Top Targeted IPs / <code>/metrics/targets</code>.</li></ul><h2 id="v2-9-0-—-targeted-ip-visibility" tabindex="-1">v2.9.0 — targeted-IP visibility <a class="header-anchor" href="#v2-9-0-—-targeted-ip-visibility" aria-label="Permalink to &quot;v2.9.0 — targeted-IP visibility&quot;">​</a></h2><ul><li><strong>Which VPS IP is being attacked</strong> — per-destination-IP counters at wire speed; the TUI dashboard gets a <em>Top Targeted IPs</em> panel (live pps/bps/share), attack-end webhook reports get a <em>Top Targeted IPs</em> field, and the metrics API gains <code>GET /metrics/targets</code>. Built for dedicated hosts with routed/bridged VMs. <a href="/pingless-studios-docs/openshield-xdp/getting-started/vps-deployment">Deployment models</a></li></ul><h2 id="v2-8-3-—-audit-hardening-pass" tabindex="-1">v2.8.3 — audit hardening pass <a class="header-anchor" href="#v2-8-3-—-audit-hardening-pass" aria-label="Permalink to &quot;v2.8.3 — audit hardening pass&quot;">​</a></h2><ul><li><strong>Security:</strong> TCP <code>doff&lt;5</code> rejected (a doff=0 ACK could mint the established-connection mark without a real session); null-flag and Xmas scans now actually reach the flag validator; baseline anchor u64 wrap on busy links fixed; blind RSTs enforce the freshness window; API guard no longer drops multi-MSS request bodies or locks out IPv6 in allowlist-only mode.</li><li><strong>Correctness:</strong> IPv6 amp check honors extension headers; L7 runtime-promoted rules (slots 1-15) were silently inert; TUI ban countdown clock-domain mix; fetcher apply errors swallowed; config-reload RMW race; panic recovery reverting runtime edits; <code>spike_recovery_time</code>/<code>baseline_update_interval</code> validation (flap/panic paths).</li><li><strong>Performance:</strong> ban sweep loses ~400k syscalls/5s on feed-loaded hosts; bounded top-N map iterators; rate-limited new-source events with an exact kernel counter; async capped attacks.json persistence; no snapshot marshal with zero clients.</li></ul><h2 id="v2-8-2-—-new-source-metric-fix" tabindex="-1">v2.8.2 — new-source metric fix <a class="header-anchor" href="#v2-8-2-—-new-source-metric-fix" aria-label="Permalink to &quot;v2.8.2 — new-source metric fix&quot;">​</a></h2><ul><li><strong>New Src/s was stuck at 0</strong> — the userspace reader queried the single-entry new-source map with a per-CPU slice lookup, which always failed silently. The kernel now keeps a monotonic total alongside the 1s windowed count; the displayed rate is exact at any poll interval. The new-source temp-ban rule itself was verified firing live (400–540k new src/s during a rotating-spoof flood).</li></ul><h2 id="v2-8-1-—-repeat-offender-hardening-all-port-coverage" tabindex="-1">v2.8.1 — repeat-offender hardening, all-port coverage <a class="header-anchor" href="#v2-8-1-—-repeat-offender-hardening-all-port-coverage" aria-label="Permalink to &quot;v2.8.1 — repeat-offender hardening, all-port coverage&quot;">​</a></h2><ul><li><strong>Repeat-offender hardening</strong> — bans backed by <em>verified</em> heavy evidence (both PPS and BPS ≥ 3× threshold, no established TCP session) accrue a separate heavy-hit count: 2nd verified heavy ban = <strong>1 day</strong>, 3rd+ = <strong>7 days</strong> (<code>static.repeat_ban_duration_2/3</code>). Bulk transfers can never collect heavy marks; borderline crossers keep the normal ladder.</li><li><strong>All-port protection</strong> — <code>ct_server_port_max</code> default 65535: services on high ports (&gt;30000) are fully covered; outbound connections (apt/curl) still work via the SYN-ACK bootstrap.</li><li><strong>Scoring determinism fix</strong> — an odd <code>bpf_ktime</code> low bit was decoded as a spurious window reset on ~half of all packets; sampling and scoring are now exact.</li><li><strong>Heavy-evidence measurement fix</strong> — fast floods banned on 256-packet samples now have their <em>true</em> arrival rate extrapolated, so hardening actually engages on real floods.</li><li><strong>Port-cap starvation fix</strong> — attack-capped sources accrue suspicion before the cap drop (previously throttled forever, never banned).</li><li><strong>Ban-expiry clock fix</strong> — bans on hosts that suspend (laptops, suspended/migrated VMs) were reaped as instantly-expired; userspace now reads the same CLOCK_MONOTONIC as the kernel.</li></ul><h2 id="v2-8-0-—-smarter-classification-xdp-trace-api-guard-fixed-tui-chrome" tabindex="-1">v2.8.0 — smarter classification, XDP trace, API guard, fixed TUI chrome <a class="header-anchor" href="#v2-8-0-—-smarter-classification-xdp-trace-api-guard-fixed-tui-chrome" aria-label="Permalink to &quot;v2.8.0 — smarter classification, XDP trace, API guard, fixed TUI chrome&quot;">​</a></h2><ul><li><strong>Multi-signal classifier</strong> — new types (ACK_FLOOD, SYNACK_REFLECTION, FRAG_FLOOD, CARPET_BOMB, PORT_SCAN), UDP_AMPLIFICATION revived with subtypes (dns/ntp/ssdp/…), driven by new kernel counters (TCP flags, fragments, 12-slot reflector source-port histogram). Research-backed rules (FastNetMon, CICDDoS2019, Kitsune).</li><li><strong>XDP decision trace</strong> — every attack&#39;s forensics dir now has xdp-trace.log: each verdict with ns-accurate timestamps, sampled 1/64 per CPU, zero peacetime cost.</li><li><strong>API port guard</strong> — basic L7 for the metrics/control port: TCP-only + HTTP-method payloads + its own allowlist (metrics.whitelist), synced live.</li><li><strong>TUI fixed chrome</strong> — status/nav pinned top, keybind footer pinned bottom, every screen scrolls in a bounded viewport with scrollbars.</li><li><strong>Behavior engine</strong>: port fan-out scan detection. <strong>Baseline</strong>: anomalous days auto-flagged. Whitelisted bulk traffic no longer declares attacks.</li></ul><h2 id="v2-7-0-—-full-management-api-player-protection-hardened" tabindex="-1">v2.7.0 — full management API + player protection hardened <a class="header-anchor" href="#v2-7-0-—-full-management-api-player-protection-hardened" aria-label="Permalink to &quot;v2.7.0 — full management API + player protection hardened&quot;">​</a></h2><ul><li><strong>Management API</strong> — new read endpoints (/metrics/baseline, /metrics/geo, /metrics/alerter, /metrics/autofetch, /metrics/access, /metrics/schedule) and a <code>control_enabled</code>-gated control API: config get/set, whitelist/blacklist, geo toggle, baseline export/import/delete-day, autofetch, schedule, block-pattern, attack bulk-ban jobs. Everything the TUI does, over HTTP. <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">API reference</a></li><li><strong>Player protection, flood-tested</strong> — the protected-source snapshot now fills in ~0.5s via batch map ops (plain iteration finished after the attack) and protects only proven pre-attack sources (established or first-seen ≥15s before declaration) — verified live: players flat through a rotating flood.</li></ul><h2 id="v2-6-0-—-adaptive-granularity-live-nic-tuning-toggle-baseline-day-summaries" tabindex="-1">v2.6.0 — adaptive granularity, live NIC-tuning toggle, baseline day summaries <a class="header-anchor" href="#v2-6-0-—-adaptive-granularity-live-nic-tuning-toggle-baseline-day-summaries" aria-label="Permalink to &quot;v2.6.0 — adaptive granularity, live NIC-tuning toggle, baseline day summaries&quot;">​</a></h2><ul><li><code>attack_poll_divisor</code> (default 4): polling jumps to 250ms during attacks only — zero peacetime CPU cost; <code>poll_interval</code> accepts fractional seconds.</li><li>NIC tuning toggle (<code>T</code> in the TUI) applies/reverts instantly, with the jitter tradeoff explained in the confirmation.</li><li>Baseline history rows show TCP/UDP splits and ▲/▼ deviation markers vs your median day.</li></ul><h2 id="v2-5-x-—-udp-player-protection-geo-ux-webhook-health-jitter-fix" tabindex="-1">v2.5.x — UDP player protection, geo UX, webhook health, jitter fix <a class="header-anchor" href="#v2-5-x-—-udp-player-protection-geo-ux-webhook-health-jitter-fix" aria-label="Permalink to &quot;v2.5.x — UDP player protection, geo UX, webhook health, jitter fix&quot;">​</a></h2><ul><li><strong>v2.5.0</strong> — protected-source snapshot map (Bedrock/UDP players survive floods), geo tab live job progress, webhook delivery panel in the Status tab, keybind pills + segmented status bar.</li><li><strong>v2.5.1</strong> — NIC tuning became opt-in (<code>nic_tuning</code>, default off): the coalescing it applied was the dedicated-host jitter source.</li></ul><h2 id="v2-4-x-—-baseline-memory-ml-tab-smart-preset-blending-honest-reports" tabindex="-1">v2.4.x — baseline memory (ML tab), smart preset blending, honest reports <a class="header-anchor" href="#v2-4-x-—-baseline-memory-ml-tab-smart-preset-blending-honest-reports" aria-label="Permalink to &quot;v2.4.x — baseline memory (ML tab), smart preset blending, honest reports&quot;">​</a></h2><ul><li><strong>30-day baseline memory</strong> — daily snapshots merged recency-weighted with the live EMA; one weird day can&#39;t tilt detection. TUI ML tab (<code>m</code>): learning state, live vs merged, thresholds, full history. <a href="/pingless-studios-docs/openshield-xdp/user-guide/baseline-ml">Guide</a></li><li><strong>Delete-a-day reconfiguration</strong> — a poisoned day (attack bypassed detection) can be deleted; the baseline reconfigures instantly. <code>D</code> resets today&#39;s live baseline for same-day bypasses.</li><li><strong>Baseline import/export</strong> — move trained baselines between servers.</li><li><strong>Smart multi-profile blending</strong> — multiple workload selections merge by semantics, not averages: rate ceilings = union of legit needs, scoring = strictest, FP-prone detections only where all agree.</li><li><strong>Preset retune</strong> — Balanced actually bans sustained 2× abuse; Hosting/Performance/Database bypass classes closed.</li><li><strong>Honest attack reports</strong> — median-based recovery (3s spikes no longer linger for minutes), real attacker IP counts (no more 100k phantom IPs), geo breakdown only from elevated intervals, Mbps/Kbps formatting.</li><li><strong>Alert pipeline overhaul</strong> — attack-end reports can&#39;t be lost, lifecycle alerts get queue priority, Discord 429 handling, embedded banner.</li><li><strong>Behavior engine race fixed</strong>; <code>attack_start_mono</code> preservation (the MC disconnect bug).</li></ul><h2 id="v2-3-3-—-boot-autostart-crash-immunity" tabindex="-1">v2.3.3 — Boot autostart &amp; crash-immunity <a class="header-anchor" href="#v2-3-3-—-boot-autostart-crash-immunity" aria-label="Permalink to &quot;v2.3.3 — Boot autostart &amp; crash-immunity&quot;">​</a></h2><ul><li><strong><code>openshield load -always</code></strong> — one flag enables auto-load on every boot via the systemd unit. Self-heals a missing unit file from the pristine copy in <code>/opt/openshield/lib</code>, and verifies the enable actually took.</li><li><strong>Admin IP protection, guaranteed</strong> — the loader binary (what systemd runs at boot) now also auto-whitelists your SSH source IP; the persisted entry is re-applied on every boot before the first packet is judged.</li><li><strong>Hardened systemd unit</strong> — waits for <code>network-online.target</code> (no more racing the interface at boot), and <code>StartLimitIntervalSec=0</code> means a crash loop never puts the firewall into a permanent failed state.</li><li><strong>Silent-crash immunity baked into every binary</strong> — on some kernels/hypervisors the Go runtime&#39;s async preemption killed the loader instantly with no output. All binaries now self-apply the documented workaround (<code>GODEBUG=asyncpreemptoff=1</code>) via a transparent re-exec, so manual runs are as safe as the systemd unit.</li></ul><h2 id="v2-3-2-—-cli-help-system-tui-bugfix-sweep" tabindex="-1">v2.3.2 — CLI help system &amp; TUI bugfix sweep <a class="header-anchor" href="#v2-3-2-—-cli-help-system-tui-bugfix-sweep" aria-label="Permalink to &quot;v2.3.2 — CLI help system &amp; TUI bugfix sweep&quot;">​</a></h2><ul><li><strong>Per-command help pages</strong> — <code>openshield help &lt;command&gt;</code> / <code>--help</code> anywhere, driven by one registry so overall and per-command help can never drift.</li><li><strong>18 TUI fixes</strong> — geo-tab crash on empty search, never-block input digit handling, traffic screen wraps below 140 columns, typed <code>config_update</code> replies (live config edits no longer look lost), confirm dialogs honor Ctrl+C, uptime-based health badges, narrow-terminal layout, scrollable help overlay, complete keybind docs, input validation, and more.</li></ul><h2 id="v2-3-1-—-self-traffic-exclusion-startup-warmup" tabindex="-1">v2.3.1 — Self-traffic exclusion &amp; startup warmup <a class="header-anchor" href="#v2-3-1-—-self-traffic-exclusion-startup-warmup" aria-label="Permalink to &quot;v2.3.1 — Self-traffic exclusion &amp; startup warmup&quot;">​</a></h2><ul><li><strong>Your own downloads no longer fake attacks</strong> — replies to the server&#39;s outbound connections (GeoIP updates, blocklist fetches, apt) are excluded from attack-detection and baseline-learning rates. Root-caused: the global counters ran before every exemption. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-own-downloads-never-fake-an-attack">How it works</a></li><li><strong><code>attack_warmup_sec</code></strong> (default 20) — no attack declaration in the first seconds after loader start; per-IP mitigation unaffected.</li></ul><h2 id="v2-3-0-—-smarter-feeds-bigger-maps" tabindex="-1">v2.3.0 — Smarter feeds, bigger maps <a class="header-anchor" href="#v2-3-0-—-smarter-feeds-bigger-maps" aria-label="Permalink to &quot;v2.3.0 — Smarter feeds, bigger maps&quot;">​</a></h2><ul><li><strong>Auto-fetch <code>vps</code> / <code>dedicated</code> modes</strong> — dedicated mode skips known cloud/hosting provider ranges (Cloudflare, AWS, GCP live lists + offline fallback) so customer nodes on a dedicated box are never feed-banned.</li><li><strong>List hygiene</strong> — whitelabel (never-block) syncing with the whitelist, blacklist↔whitelist conflict resolution.</li><li><strong>2M-entry ban maps</strong> (IPv4) — million-IP botnets fit with headroom (~1 GB).</li></ul><h2 id="v2-2-x-—-geo-blocking-alert-quality" tabindex="-1">v2.2.x — Geo blocking &amp; alert quality <a class="header-anchor" href="#v2-2-x-—-geo-blocking-alert-quality" aria-label="Permalink to &quot;v2.2.x — Geo blocking &amp; alert quality&quot;">​</a></h2><ul><li><strong>Geo country blocking</strong> — one keypress blocks a country; ranges resolve from MaxMind GeoLite2 into permanent subnet bans, with persisted records and one-keypress unblock. Geo analytics (top attacking countries with flags, IPs, PPS, Gbps, share %) in attack-end reports and daily/weekly/monthly reports.</li><li><strong>Ban notes</strong> — optional notes on every ban; geo blocks use them for surgical unblocking.</li><li><strong>Alert cadence rework</strong> — growing-interval progress updates, guaranteed end-of-attack delivery with the full report, oversized-forensics fallback message.</li><li><strong>Port-cap player protection</strong> — established and pre-attack sources exempt from the per-port attack cap.</li></ul><h2 id="v2-1-x-—-metrics-obfuscation-rotation-proof-caps" tabindex="-1">v2.1.x — Metrics, obfuscation, rotation-proof caps <a class="header-anchor" href="#v2-1-x-—-metrics-obfuscation-rotation-proof-caps" aria-label="Permalink to &quot;v2.1.x — Metrics, obfuscation, rotation-proof caps&quot;">​</a></h2><ul><li><strong>Metrics HTTP API</strong> — optional endpoint with everything the TUI shows; API key (yours or auto-generated), rate limits, allowlist.</li><li><strong>Obfuscated prebuilt releases</strong> — garble-built binaries, zero source in the production zip; dual packaging (bin + src).</li><li><strong>Attack per-port aggregate cap</strong> — the rotation-proof answer to spoofed floods.</li><li><strong>New-source temp bans</strong> — replaces drop-only handling of source bursts.</li><li><strong>Forensics config evidence</strong> — every attack bundle includes the config (with change timestamps) active during it.</li><li><strong>Runtime config edits persist</strong> — TUI/live edits write through to the YAML.</li></ul><h2 id="v2-0-0-—-the-sftp-fix" tabindex="-1">v2.0.0 — The SFTP fix <a class="header-anchor" href="#v2-0-0-—-the-sftp-fix" aria-label="Permalink to &quot;v2.0.0 — The SFTP fix&quot;">​</a></h2><ul><li><strong>Established-connection exemption (A2)</strong> — proven TCP connections (handshake + real data) are exempt from rate scoring. Bulk transfers — SFTP uploads, backups, replication — never get banned again. <a href="/pingless-studios-docs/openshield-xdp/features/silent-guardians#your-sftp-uploads-never-get-you-banned">The full story</a></li><li><strong>Per-port threshold overrides (C)</strong> — custom PPS/BPS limits for specific ports or port ranges, replacing both normal and attack-mode thresholds on those ports only.</li></ul>',81)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
